(()=>{let e=(()=>{let e=document.querySelectorAll(".article-detail__content figure");return{setEventClick:function(){e.forEach(e=>{e.addEventListener("click",e=>{var t=e.target.dataset.event;try{this[t](e.target)}catch(e){console.log("setEventClick error: ",e)}})})},setWidthAsContainer:t=>{e.forEach(e=>{e.style.width=window.outerWidth-t+"px"})},addCopylink:()=>{e.forEach(e=>{e.insertAdjacentHTML("afterbegin",'<div class="article-detail__content_copylink" data-event="copyCode"></div>')})},copyCode:e=>{e=e.parentElement.querySelector(".hljs").innerText;navigator.clipboard.writeText(e).then(function(){console.log("Текст успешно скопирован в буфер обмена!")}).catch(function(e){console.error("Ошибка при копировании текста: ",e)})}}})();document.addEventListener("DOMContentLoaded",function(){window.hljs&&hljs.highlightAll(),document.querySelectorAll(".btn.btn__back--l-arrow").forEach(e=>{e.addEventListener("click",()=>{var e=document.referrer;window.location.href=e||"/"})}),e.setEventClick(),e.addCopylink()})})();